var fs = require('fs');
var path = require('path');

var ascxPath = path.join(__dirname, '..', 'HOS', 'Controls', 'Information', 'TiemChung', 'SectionTiemChung.ascx');
var lines = fs.readFileSync(ascxPath, 'utf8').split(/\r?\n/);
var chunk = lines.slice(10, 583).join('\n');
var html = '<div class="tiem-chung-page" data-tiem-chung-root="1">\n<div class="tiem-chung-page-body">\n' +
    chunk + '\n</div>\n</div>';

var outDir = path.join(__dirname, '..', 'SQL', 'CHUYENDOI', 'TiemChung');
fs.mkdirSync(outDir, { recursive: true });

var fragmentPath = path.join(outDir, '_html_seed_fragment.txt');
fs.writeFileSync(fragmentPath, html, 'utf8');

function sqlEscape(value) {
    return value.replace(/'/g, "''");
}

var chunks = [];
var size = 3500;
for (var i = 0; i < html.length; i += size) {
    chunks.push("N'" + sqlEscape(html.substring(i, i + size)) + "'");
}

var sql = "USE [thienhaso_WEB_His_TimTamDuc_2025]\r\nGO\r\n\r\n";
sql += "SET NOCOUNT ON\r\nSET XACT_ABORT ON\r\n\r\n";
sql += "IF OBJECT_ID(N'dbo.CMS_TiemChungPageVersion', N'U') IS NULL\r\n";
sql += "   OR OBJECT_ID(N'dbo.CMS_TiemChungPage_SaveCMS', N'P') IS NULL\r\n";
sql += "BEGIN\r\n";
sql += "    RAISERROR(N'Chua co cau truc Tiem Chung Full Page. Hay chay file 01 truoc.', 16, 1)\r\n";
sql += "    RETURN\r\n";
sql += "END\r\n\r\n";
sql += "DECLARE @HtmlBodyVi NVARCHAR(MAX) = CAST(N'' AS NVARCHAR(MAX))\r\n";
for (var c = 0; c < chunks.length; c++) {
    sql += "SET @HtmlBodyVi = @HtmlBodyVi + " + chunks[c] + "\r\n";
}
sql += "\r\nEXEC dbo.CMS_TiemChungPage_SaveCMS\r\n";
sql += "    @Title = N'Tiêm Chủng An Toàn Cho Người Bệnh Nền | Tâm Đức',\r\n";
sql += "    @Slug = N'tiem-chung-tam-duc',\r\n";
sql += "    @MetaDescription = N'Dịch vụ tiêm chủng Bệnh viện Tim Tâm Đức — tư vấn bởi bác sĩ tim mạch.',\r\n";
sql += "    @HtmlBodyVi = @HtmlBodyVi,\r\n";
sql += "    @HtmlBodyEn = @HtmlBodyVi,\r\n";
sql += "    @CssText = NULL,\r\n";
sql += "    @ProjectJsonVi = NULL,\r\n";
sql += "    @ProjectJsonEn = NULL,\r\n";
sql += "    @Publish = 1,\r\n";
sql += "    @UserName = N'seed'\r\n";
sql += "GO\r\n";

var sqlPath = path.join(outDir, '02_CMS_TiemChungFullPage_Insert_NoiDungHienTai.sql');
fs.writeFileSync(sqlPath, sql, 'utf8');
console.log('Wrote', sqlPath, 'length', html.length);

