    ['/ve-chung-toi-tam-duc/', '/tiem-chung-tam-duc/'],
    ['About Full Page', 'Tiem Chung Full Page'],
    ['AboutPageVersionID', 'TiemChungPageVersionID'],
    ['#about-page-base-style', '#tiem-chung-page-base-style'],
    ['window.aboutPageEditor', 'window.tiemChungPageEditor'],
    ['About hi\u1ec7n t\u1ea1i', 'Tiem Chung hi\u1ec7n t\u1ea1i'],
    ['About Page th\u1ea5t b\u1ea1i', 'Tiem Chung Page th\u1ea5t b\u1ea1i'],
    ['quy\u1ec1n xem About Page', 'quy\u1ec1n xem Tiem Chung Page'],
    ['n\u1ed9i dung About hi\u1ec7n t\u1ea1i', 'n\u1ed9i dung Tiem Chung hi\u1ec7n t\u1ea1i'],
    ['L\u01b0u About Page', 'L\u01b0u Tiem Chung Page'],
    ['x\u1eed l\u00fd About Page', 'x\u1eed l\u00fd Tiem Chung Page'],
    ['L\u1ecbch s\u1eed About Page', 'L\u1ecbch s\u1eed Tiem Chung Page'],
