for (var i = 0; i < reps.length; i++) {
    s = s.split(reps[i][0]).join(reps[i][1]);
}

// Replace default blocks section with Tiem Chung blocks
var blocksStart = s.indexOf("var blocks = [");
var blocksEnd = s.indexOf("];", blocksStart);
if (blocksStart >= 0 && blocksEnd > blocksStart) {
    var tcBlocks = "var blocks = [\n" +
        "            { id: 'tc-hero', title: 'Hero', desc: 'Banner dau trang tiem chung', icon: 'bi-rocket-takeoff', category: 'Tiem Chung', content: '<section class=\"hero\"><div class=\"container\"><div class=\"hero-text\"><h1>Tieu de Hero</h1><p class=\"sub\">Mo ta ngan.</p></div></div></section>' },\n" +
        "            { id: 'tc-audience', title: 'Doi tuong', desc: '4 the audience', icon: 'bi-people', category: 'Tiem Chung', content: '<section class=\"section audience-section\"><div class=\"container\"><h2 class=\"section-title\">Ai nen duoc tu van?</h2><div class=\"audience-grid\"><article class=\"audience-card\"><div class=\"audience-card-body\"><h3>Nhom 1</h3><p>Mo ta.</p></div></article></div></div></section>' },\n" +
        "            { id: 'tc-vaccine-tabs', title: 'Vaccine tabs', desc: 'Tab danh muc vaccine', icon: 'bi-capsule', category: 'Tiem Chung', content: '<section class=\"section alt-bg\"><div class=\"container\"><div class=\"vaccine-tabs-layout\"><div class=\"vaccine-tab-scroll\" data-vaccine-scroll=\"\"><div class=\"vaccine-tab-list\" role=\"tablist\"><button type=\"button\" class=\"vaccine-tab active\" role=\"tab\" data-target=\"panel-cum\">Cum mua</button></div></div><div class=\"vaccine-panels\"><div class=\"vaccine-panel active\" id=\"panel-cum\" role=\"tabpanel\"><h3>Cum mua</h3><p>Noi dung panel.</p></div></div></div></div></section>' },\n" +
        "            { id: 'tc-price', title: 'Bang gia', desc: 'Bang gia vaccine', icon: 'bi-currency-dollar', category: 'Tiem Chung', content: '<section class=\"section price-section\" id=\"bang-gia\"><div class=\"container\"><h2 class=\"section-title\">Bang gia</h2><table class=\"price-table\"><tbody><tr><td>Dich vu</td><td class=\"price-col\">0d</td></tr></tbody></table></div></section>' },\n" +
        "            { id: 'tc-faq', title: 'FAQ', desc: 'Cau hoi thuong gap', icon: 'bi-question-circle', category: 'Tiem Chung', content: '<section class=\"section alt-bg faq-section\" id=\"faq\"><div class=\"container\"><div class=\"faq-list\"><details class=\"faq-item\"><summary class=\"faq-q\"><span>Cau hoi?</span></summary><div class=\"faq-a\"><div class=\"faq-a-inner\"><div class=\"faq-a-content\">Tra loi.</div></div></div></details></div></div></section>' },\n" +
        "            { id: 'tc-section', title: 'Section', desc: 'Khoi noi dung chung', icon: 'bi-window', category: 'Cau truc', content: '<section class=\"section\"><div class=\"container\"><h2 class=\"section-title\">Tieu de</h2><p class=\"section-lede\">Noi dung.</p></div></section>' },\n" +
        "            { id: 'tc-text', title: 'Doan van', desc: 'Double-click de sua', icon: 'bi-text-paragraph', category: 'Noi dung', content: '<p>Nhap noi dung tai day.</p>' },\n" +
        "            { id: 'tc-image', title: 'Hinh anh', desc: 'Chon anh bang CKFinder', icon: 'bi-image', category: 'Noi dung', content: '<figure><img src=\"/Controls/Information/TiemChung/img/doctor.png\" alt=\"Hinh anh\" style=\"max-width:100%;height:auto;\" /></figure>' }\n" +
        "        ]";
    s = s.substring(0, blocksStart) + tcBlocks + s.substring(blocksEnd + 2);
}

fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'tiem-chung-page-builder.js'), s, 'utf8');
