using System;
using System.Web;
using DCore;

namespace InformationCMS.Controls.TDLanding3.TiemChung
{
    public partial class TiemChungPageBuilder : ControlBase
    {
        protected string HandlerUrl
        {
            get { return ResolveUrl("~/Controls/3Landing/TiemChung/TiemChungPageHandler.ashx"); }
        }

        protected string CanEditValue
        {
            get { return "1"; }
        }

        protected string DefaultSourceUrlEncoded
        {
            get
            {
                string value = Request["source"];
                if (string.IsNullOrEmpty(value)) value = GetDefaultFrontendUrl();
                return HttpUtility.HtmlAttributeEncode(value);
            }
        }

        protected string FrontendUrlEncoded
        {
            get
            {
                string value = Request["frontend"];
                if (string.IsNullOrEmpty(value)) value = GetDefaultFrontendUrl();
                return HttpUtility.HtmlAttributeEncode(value);
            }
        }

        private static string GetDefaultFrontendUrl()
        {
            string root = CMSGlobal.WebsiteRoot;
            if (string.IsNullOrWhiteSpace(root))
                return "/tiem-chung-tam-duc/";
            return root.Trim().TrimEnd('/') + "/tiem-chung-tam-duc/";
        }

        protected void Page_Load(object sender, EventArgs e)
        {
        }
    }
}

