                context.Response.StatusCode = 500;
                WriteJson(context, false, "Lỗi hệ thống khi xử lý Tiem Chung Page.", null);
            }
        }

        private static void HandleGet(HttpContext context)
        {
            SessionUser user = RequireLogin(context);
            if (user == null) return;

            INFO_Information info = new INFO_Information();
            DataTable data = info.GetDataTable("CMS_TiemChungPage_GetCMS");
            WriteJson(context, true, "OK", data == null || data.Rows.Count < 1 ? null : RowToDictionary(data.Rows[0]));
        }

        private static void HandleVersions(HttpContext context)
        {
            SessionUser user = RequireLogin(context);
            if (user == null) return;

            INFO_Information info = new INFO_Information();
            DataTable data = info.GetDataTable("CMS_TiemChungPage_VersionListCMS");
            List<Dictionary<string, object>> rows = new List<Dictionary<string, object>>();
            if (data != null)
            {
                foreach (DataRow row in data.Rows)
                    rows.Add(RowToDictionary(row));
            }
            WriteJson(context, true, "OK", rows);
        }

        private static void HandleSave(HttpContext context)
        {
            SessionUser user = RequireLogin(context);
            if (user == null) return;

            TiemChungPageSaveRequest request = DeserializeBody<TiemChungPageSaveRequest>(context);
            if (request == null)
            {
                WriteJson(context, false, "Dữ liệu gửi lên không hợp lệ.", null);
                return;
            }

            request.Title = (request.Title ?? string.Empty).Trim();
            request.Slug = NormalizeSlug(request.Slug);
            if (request.Title.Length == 0 || request.Slug.Length == 0)
            {
                WriteJson(context, false, "Tiêu đề và slug là bắt buộc.", null);
                return;
            }
            if (string.IsNullOrWhiteSpace(request.HtmlBodyVi))
            {
                WriteJson(context, false, "Nội dung tiếng Việt không được để trống.", null);
                return;
            }

            string htmlVi = SanitizeHtml(request.HtmlBodyVi);
            string htmlEn = SanitizeHtml(request.HtmlBodyEn);
            string css = SanitizeCss(request.CssText);
            if (!IsCssScoped(css))
            {
                WriteJson(context, false, "CSS Tiem Chung phải được giới hạn trong .tiem-chung-page.", null);
                return;
            }

            INFO_Information info = new INFO_Information();
            DataTable result = info.GetDataTable(
                "CMS_TiemChungPage_SaveCMS",
                "@Title", request.Title,
                "@Slug", request.Slug,
                "@MetaDescription", EmptyToDbNull(request.MetaDescription),
                "@HtmlBodyVi", htmlVi,
                "@HtmlBodyEn", EmptyToDbNull(htmlEn),
                "@CssText", EmptyToDbNull(css),
                "@ProjectJsonVi", EmptyToDbNull(request.ProjectJsonVi),
                "@ProjectJsonEn", EmptyToDbNull(request.ProjectJsonEn),
                "@Publish", request.Publish ? 1 : 0,
                "@UserName", user.UserName
            );

            WriteJson(context, true, request.Publish ? "Đã xuất bản Tiem Chung Page." : "Đã lưu bản nháp.",
                result == null || result.Rows.Count < 1 ? null : RowToDictionary(result.Rows[0]));
        }

        private static void HandleRestore(HttpContext context)
        {
            SessionUser user = RequireLogin(context);
            if (user == null) return;

            TiemChungPageRestoreRequest request = DeserializeBody<TiemChungPageRestoreRequest>(context);
            if (request == null || request.TiemChungPageVersionID < 1)
            {
                WriteJson(context, false, "Version không hợp lệ.", null);
                return;
            }

            INFO_Information info = new INFO_Information();
            DataTable result = info.GetDataTable(
                "CMS_TiemChungPage_RestoreCMS",
                "@TiemChungPageVersionID", request.TiemChungPageVersionID,
                "@UserName", user.UserName
            );
            WriteJson(context, true, "Đã phục hồi và xuất bản version được chọn.",
                result == null || result.Rows.Count < 1 ? null : RowToDictionary(result.Rows[0]));
        }

        private static SessionUser RequireLogin(HttpContext context)
        {
            SessionUser user = context.Session[Globals.USER] as SessionUser;
            if (user == null)
            {
                context.Response.StatusCode = 401;
                WriteJson(context, false, "Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.", null);
                return null;
            }
            return user;
        }

        private static T DeserializeBody<T>(HttpContext context) where T : class
        {
            if (context.Request.InputStream == null) return null;
            context.Request.InputStream.Position = 0;
            using (StreamReader reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
            {
                string body = reader.ReadToEnd();
                if (string.IsNullOrWhiteSpace(body)) return null;
                return CreateSerializer().Deserialize<T>(body);
            }
        }

        public static string SanitizeHtml(string html)
        {
            if (string.IsNullOrEmpty(html)) return string.Empty;

            string value = html;
            value = Regex.Replace(value, @"<%[\s\S]*?%>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<script\b[^>]*>[\s\S]*?</script\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<style\b[^>]*>[\s\S]*?</style\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<(?:iframe|object|embed|applet|base|meta|link)\b[^>]*>[\s\S]*?</(?:iframe|object|embed|applet)\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"<(?:iframe|object|embed|applet|base|meta|link)\b[^>]*/?>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"</?(?:html|head|body|form)\b[^>]*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"</?asp:[^>]*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"\srunat\s*=\s*(?:""[^""]*""|'[^']*'|[^\s>]+)", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"\son\w+\s*=\s*(?:""[^""]*""|'[^']*'|[^\s>]+)", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"javascript\s*:", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"data\s*:\s*text/html", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"expression\s*\(", "blocked(", RegexOptions.IgnoreCase);
            return value;
        }

        public static string SanitizeCss(string css)
        {
            if (string.IsNullOrEmpty(css)) return string.Empty;

            string value = Regex.Replace(css, @"</\s*style\s*>", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"@import\b[^;]*;", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"expression\s*\(", "blocked(", RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"javascript\s*:", string.Empty, RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"behavior\s*:", "blocked-behavior:", RegexOptions.IgnoreCase);
            value = Regex.Replace(value, @"-moz-binding\s*:", "blocked-binding:", RegexOptions.IgnoreCase);
            return value;
        }

        private static bool IsCssScoped(string css)
        {
            if (string.IsNullOrWhiteSpace(css)) return true;

            string value = Regex.Replace(css, @"/\*[\s\S]*?\*/", string.Empty);
            MatchCollection blocks = Regex.Matches(value, @"(?:(?<=^)|(?<=[{}]))\s*([^{}]+)\{");
            foreach (Match block in blocks)
            {
                string prelude = block.Groups[1].Value.Trim();
                if (prelude.Length == 0 || prelude[0] == '@' || IsKeyframeStep(prelude))
                    continue;

                foreach (string selector in SplitCssSelectors(prelude))
                {
                    string item = selector.Trim();
                    if (!StartsWithTiemChungScope(item))
                        return false;
                }
            }
            return true;
        }

        private static bool IsKeyframeStep(string value)
        {
            if (string.Equals(value, "from", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "to", StringComparison.OrdinalIgnoreCase))
                return true;

            string[] parts = value.Split(',');
            for (int i = 0; i < parts.Length; i++)
            {
                string part = parts[i].Trim();
                if (!Regex.IsMatch(part, @"^\d+(?:\.\d+)?%$"))
                    return false;
            }
            return parts.Length > 0;
        }

        private static bool StartsWithTiemChungScope(string selector)
        {
            const string scope = ".tiem-chung-page";
            if (!selector.StartsWith(scope, StringComparison.Ordinal)) return false;
            if (selector.Length == scope.Length) return true;

            char next = selector[scope.Length];
            return char.IsWhiteSpace(next) || next == '>' || next == '+' || next == '~'
                || next == '.' || next == '#' || next == ':' || next == '[';
        }

        private static List<string> SplitCssSelectors(string value)
        {
            List<string> result = new List<string>();
            int start = 0;
            int round = 0;
            int square = 0;
            char quote = '\0';

            for (int i = 0; i < value.Length; i++)
            {
                char current = value[i];
                if (quote != '\0')
                {
                    if (current == '\\') i++;
                    else if (current == quote) quote = '\0';
                    continue;
                }
                if (current == '\'' || current == '"') quote = current;
                else if (current == '(') round++;
                else if (current == ')') round--;
                else if (current == '[') square++;
                else if (current == ']') square--;
                else if (current == ',' && round == 0 && square == 0)
                {
                    result.Add(value.Substring(start, i - start));
                    start = i + 1;
                }
            }
            result.Add(value.Substring(start));
            return result;
        }

        private static string NormalizeSlug(string slug)
        {
            string value = (slug ?? string.Empty).Trim().ToLowerInvariant().Replace(" ", "-");
            value = Regex.Replace(value, @"[^a-z0-9\-]", string.Empty);
