                return;
            }

            string fullName = SanitizeInput(txtFullName.Text, 250);
            string phone = SanitizeInput(txtPhone.Text, 20);
            string email = SanitizeInput(txtEmail.Text.Trim(), 250);
            string content = SanitizeContent(txtContent.Text);

            if (string.IsNullOrWhiteSpace(fullName))
            {
                ShowRegisterMessage("Vui lòng nhập họ và tên.", false);
                return;
            }

            if (string.IsNullOrWhiteSpace(phone))
            {
                ShowRegisterMessage("Vui lòng nhập số điện thoại.", false);
                return;
            }

            if (!IsValidPhone(phone))
            {
                ShowRegisterMessage("Số điện thoại không hợp lệ.", false);
                return;
            }

            if (!string.IsNullOrWhiteSpace(email) && !IsValidEmail(email))
            {
                ShowRegisterMessage("Email không hợp lệ.", false);
                return;
            }

            INFO_TiemChungRegister obj = new INFO_TiemChungRegister();
            obj.FullName = fullName;
            obj.Phone = phone;
            obj.Email = string.IsNullOrWhiteSpace(email) ? null : email;
            obj.Content = string.IsNullOrWhiteSpace(content) ? null : content;
            obj.Status = StatusNew;
            obj.ClientIP = GetClientIP();

            if (!obj.Add() || obj.TiemChungRegisterID == null || obj.TiemChungRegisterID.Value <= 0)
            {
                ShowRegisterMessage("Không thể lưu thông tin đăng ký. Vui lòng thử lại sau.", false);
                return;
            }

            bool customerMailSent = false;

            if (!string.IsNullOrWhiteSpace(email))
            {
                try
                {
                    SendCustomerEmail(email, fullName, phone, content);
                    customerMailSent = true;
                }
                catch
                {
                    customerMailSent = false;
                }
            }

            if (string.IsNullOrWhiteSpace(email))
