        private static System.Net.Mail.MailMessage BuildHtmlMail(string toEmail, string subject, string htmlBody)
        {
            System.Net.Mail.MailMessage message = new System.Net.Mail.MailMessage();
            message.To.Add(new System.Net.Mail.MailAddress(toEmail));
            message.Subject = subject;
            message.SubjectEncoding = System.Text.Encoding.UTF8;
            message.Body = htmlBody;
            message.BodyEncoding = System.Text.Encoding.UTF8;
            message.IsBodyHtml = true;
            message.Priority = System.Net.Mail.MailPriority.High;
            return message;
        }

        private static void SendMailMessage(System.Net.Mail.MailMessage message)
        {
            using (System.Net.Mail.SmtpClient smtp = new System.Net.Mail.SmtpClient())
            {
                smtp.Send(message);
            }
        }

        private string GetClientIP()
        {
            string ip = Request.ServerVariables["HTTP_X_FORWARDED_FOR"];
            if (!string.IsNullOrWhiteSpace(ip))
            {
                int comma = ip.IndexOf(',');
                if (comma > 0)
                    ip = ip.Substring(0, comma);
                return ip.Trim();
            }
            return Request.UserHostAddress;
        }

        private static string SanitizeContent(string value)
        {
            if (string.IsNullOrEmpty(value))
                return string.Empty;
            return value.Trim();
        }

        private static string SanitizeInput(string value, int maxLength)
        {
            if (string.IsNullOrEmpty(value))
                return string.Empty;
            value = value.Trim();
            if (value.Length > maxLength)
                value = value.Substring(0, maxLength);
            return value;
        }

        private static bool IsValidPhone(string phone)
        {
            if (string.IsNullOrWhiteSpace(phone))
                return false;
            return PhoneRegex.IsMatch(phone.Trim());
        }

        private static bool IsValidEmail(string email)
        {
            if (string.IsNullOrWhiteSpace(email))
                return false;
            try
            {
                System.Net.Mail.MailAddress addr = new System.Net.Mail.MailAddress(email);
                return addr.Address.Equals(email, StringComparison.OrdinalIgnoreCase);
            }
            catch
            {
                return false;
            }
        }

        private void ShowRegisterMessage(string text, bool isSuccess)
        {
            pnlRegisterMessage.CssClass = "register-message";
            litRegisterMessage.Text = string.Format(
                "<p class=\"register-msg {0}\">{1}</p>",
                isSuccess ? "register-msg-success" : "register-msg-error",
                Server.HtmlEncode(text));
        }

