function getCanvasDocument() {
    if (!editor) return null;
    var frame = editor.Canvas.getFrameEl();
    if (!frame || !frame.contentDocument) return null;
    return frame.contentDocument;
}

function activateVaccineTabInDoc(doc, tab) {
    if (!doc || !tab) return;
    var targetId = tab.getAttribute('aria-controls') || tab.getAttribute('data-target');
    if (!targetId) return;

    var root = tab.closest ? tab.closest('.tiem-chung-page') : null;
    if (!root) return;

    var panel = root.querySelector('#' + targetId);
    if (!panel) return;

    var tabs = root.querySelectorAll('.vaccine-tab');
    var panels = root.querySelectorAll('.vaccine-panel');
    var t, p, item, isActive, panelItem, panelActive;

    for (t = 0; t < tabs.length; t++) {
        item = tabs[t];
        isActive = item === tab;
        if (isActive) item.classList.add('active');
        else item.classList.remove('active');
        item.setAttribute('aria-selected', isActive ? 'true' : 'false');
        item.tabIndex = isActive ? 0 : -1;
    }

    for (p = 0; p < panels.length; p++) {
        panelItem = panels[p];
        panelActive = panelItem === panel;
        if (panelActive) panelItem.classList.add('active');
        else panelItem.classList.remove('active');
        panelItem.hidden = !panelActive;
        panelItem.setAttribute('aria-hidden', panelActive ? 'false' : 'true');
        panelItem.classList.add('tc-visible');
    }
}

function syncVaccineTabsInDoc(doc) {
    if (!doc) return;
    var roots = doc.querySelectorAll('.tiem-chung-page');
    for (var r = 0; r < roots.length; r++) {
        var root = roots[r];
        var tabs = root.querySelectorAll('.vaccine-tab');
        if (!tabs.length) continue;

        var initialTab = null;
        for (var i = 0; i < tabs.length; i++) {
            if (tabs[i].classList.contains('active')) {
                initialTab = tabs[i];
                break;
            }
        }
        if (!initialTab) initialTab = tabs[0];
        if (initialTab) activateVaccineTabInDoc(doc, initialTab);
    }
}

function bindCanvasInteractions() {
    var doc = getCanvasDocument();
    if (!doc || !doc.documentElement) return;

    if (doc.documentElement.getAttribute('data-tc-builder-interactions') !== '1') {
        doc.documentElement.setAttribute('data-tc-builder-interactions', '1');
        doc.addEventListener('click', function (ev) {
            var target = ev.target;
            if (!target || !target.closest) return;
            var tab = target.closest('.vaccine-tab');
            if (!tab) return;
            activateVaccineTabInDoc(doc, tab);
        }, false);
    }

    syncVaccineTabsInDoc(doc);
}

function injectBaseCss() {

    style.textContent = (baseCss || '') + '\n' +
