private static void HandleImport(HttpContext context)
{
    SessionUser user = RequireLogin(context);
    if (user == null) return;

    string sourceUrl = (context.Request["url"] ?? string.Empty).Trim();
    int languageId = 1;
    int parsedLanguageId;
    if (int.TryParse(context.Request["languageId"], out parsedLanguageId)
        && (parsedLanguageId == 1 || parsedLanguageId == 2))
    {
        languageId = parsedLanguageId;
    }

    if (sourceUrl.Length == 0)
    {
        WriteJson(context, false, "URL frontend không hợp lệ.", null);
        return;
    }

    try
    {
        Uri fetchUri = ResolveFrontendUri(sourceUrl);
        string fetchUrl = AppendCmsTemplateQuery(fetchUri.AbsoluteUri, languageId);
        string html = DownloadFrontendHtml(fetchUrl);
        string pageHtml = ExtractTiemChungRootHtml(html);
        string baseCss = ExtractTiemChungBaseCss(html);

        if (string.IsNullOrWhiteSpace(pageHtml))
        {
            WriteJson(context, false, "Không tìm thấy .tiem-chung-page trong frontend.", null);
            return;
        }

        Dictionary<string, object> data = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        data["Html"] = pageHtml;
        data["BaseCss"] = baseCss ?? string.Empty;
        WriteJson(context, true, "OK", data);
    }
    catch (Exception ex)
    {
        System.Diagnostics.Debug.WriteLine("TiemChungPageHandler import: " + ex);
        WriteJson(context, false, "Không nạp được frontend: " + ex.Message, null);
    }
}

private static Uri ResolveFrontendUri(string sourceUrl)
{
    Uri uri;
    if (!Uri.TryCreate(sourceUrl, UriKind.Absolute, out uri))
    {
        string root = CMSGlobal.WebsiteRoot;
        if (string.IsNullOrWhiteSpace(root))
            throw new InvalidOperationException("Chưa cấu hình WebsiteRoot trong Web.config.");

        string combined = root.Trim().TrimEnd('/') + "/" + sourceUrl.Trim().TrimStart('/');
        if (!Uri.TryCreate(combined, UriKind.Absolute, out uri))
            throw new InvalidOperationException("URL frontend không hợp lệ.");
    }

    Uri allowedRoot;
    if (!Uri.TryCreate(CMSGlobal.WebsiteRoot, UriKind.Absolute, out allowedRoot))
        return uri;

    if (!string.Equals(uri.Host, allowedRoot.Host, StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException("Chỉ được nạp frontend cùng domain WebsiteRoot.");

    return uri;
}

private static string AppendCmsTemplateQuery(string url, int languageId)
{
    string separator = url.IndexOf('?') >= 0 ? "&" : "?";
    return url + separator + "cmsTemplate=1&languageId=" + languageId.ToString();
}

private static string DownloadFrontendHtml(string url)
{
    using (WebClient client = new WebClient())
    {
        client.Encoding = Encoding.UTF8;
        client.Headers.Add("User-Agent", "TiemChungCMS/1.0");
        return client.DownloadString(url);
    }
}

private static string ExtractTiemChungBaseCss(string html)
{
    if (string.IsNullOrEmpty(html)) return string.Empty;

    Match match = Regex.Match(
        html,
        @"<style\b[^>]*\bid\s*=\s*(?:""tiem-chung-page-base-style""|'tiem-chung-page-base-style')[^>]*>([\s\S]*?)</style>",
        RegexOptions.IgnoreCase);
    if (!match.Success) return string.Empty;
    return match.Groups[1].Value;
}

private static string ExtractTiemChungRootHtml(string html)
{
    if (string.IsNullOrEmpty(html)) return string.Empty;

    int marker = html.IndexOf("data-tiem-chung-root", StringComparison.OrdinalIgnoreCase);
    if (marker < 0)
        marker = html.IndexOf("tiem-chung-page", StringComparison.OrdinalIgnoreCase);
    if (marker < 0) return string.Empty;

    int divStart = html.LastIndexOf("<div", marker, StringComparison.OrdinalIgnoreCase);
    if (divStart < 0) return string.Empty;

    return ExtractBalancedDiv(html, divStart);
}

private static string ExtractBalancedDiv(string html, int startIndex)
{
    int depth = 0;
    int index = startIndex;

    while (index < html.Length)
    {
        int tagStart = html.IndexOf('<', index);
        if (tagStart < 0) break;

        if (tagStart + 4 <= html.Length
            && string.Compare(html, tagStart, "<div", 0, 4, StringComparison.OrdinalIgnoreCase) == 0)
        {
            depth++;
        }
        else if (tagStart + 6 <= html.Length
            && string.Compare(html, tagStart, "</div", 0, 5, StringComparison.OrdinalIgnoreCase) == 0)
        {
            depth--;
            int tagEnd = html.IndexOf('>', tagStart);
            if (tagEnd < 0) break;
            if (depth == 0)
                return html.Substring(startIndex, tagEnd - startIndex + 1);
            index = tagEnd + 1;
            continue;
        }

        index = tagStart + 1;
    }

    return string.Empty;
}

