private static void ValidateFrontendUri(Uri uri)
{
    if (uri == null) return;

    if (IsLoopbackHost(uri.Host))
        return;

    Uri allowedRoot;
    if (!Uri.TryCreate(CMSGlobal.WebsiteRoot, UriKind.Absolute, out allowedRoot))
        return;

    if (!string.Equals(uri.Host, allowedRoot.Host, StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException("Chỉ được nạp frontend cùng domain WebsiteRoot hoặc localhost dev.");
}

private static bool IsLoopbackHost(string host)
{
    if (string.IsNullOrWhiteSpace(host)) return false;

    string value = host.Trim().ToLowerInvariant();
    return value == "localhost"
        || value == "127.0.0.1"
        || value == "::1"
        || value == "[::1]";
}

