            reject(new Error('Thiếu handler CMS. Rebuild và deploy lại project InformationCMS.'));
            return;
        }

        var sourcePath = (url || defaultSourceUrl || '/tiem-chung-tam-duc/').trim();
        var importUrl = handlerUrl + '?action=import&languageId=' + languageId + '&url=' + encodeURIComponent(sourcePath);
        requestJson(importUrl, 'GET', null, function (response, status) {
            if (status === 0) {
                reject(new Error('Không gọi được handler import. Kiểm tra deploy TiemChungPageHandler.ashx.'));
                return;
            }
            if (!response || !response.Success) {
                reject(new Error((response && response.Message) ? response.Message : ('Import thất bại (HTTP ' + status + ').')));
                return;
            }
            var data = response.Data || {};
            var html = data.Html || data.html || '';
            var css = data.BaseCss || data.baseCss || '';
            if (!html) {
                reject(new Error('Không tìm thấy .tiem-chung-page trong frontend.'));
                return;
            }
            resolve({ html: html, baseCss: css });
        });
    });
}

function formatImportError(error) {
    var msg = (error && error.message) ? error.message : 'Không xác định';
    if (msg === 'Failed to fetch') {
        return 'JS cũ đang gọi trực tiếp HOS (CORS). Ctrl+F5 hoặc rebuild CMS để dùng handler import (v5).';
    }
    return msg;
}

