function onCanvasVaccineTabActivate(ev) {
    var doc = ev.currentTarget;
    var target = ev.target;
    if (!target || !target.closest) return;
    var tab = target.closest('.vaccine-tab');
    if (!tab) return;

    if (ev.type === 'click') {
