function getFaqItemFromTarget(target) {
    if (!target || !target.closest) return null;
    var summary = target.closest('summary.faq-q, .faq-q');
    if (summary && summary.parentNode && summary.parentNode.tagName === 'DETAILS') {
        return summary.parentNode;
    }
    return target.closest('details.faq-item');
}

function setFaqItemOpen(item, open) {
    if (!item) return false;
    if (open) item.setAttribute('open', 'open');
    else item.removeAttribute('open');
    return true;
}

function toggleFaqItemInDoc(doc, item) {
    if (!item) return false;
    setFaqItemOpen(item, !item.hasAttribute('open'));
    return true;
}

function previewFaqFromComponent(component) {
    var doc = getCanvasDocument();
    if (!doc || !component) return;
    var el = component.getEl ? component.getEl() : null;
    if (!el) return;
    var item = null;
    if (el.tagName === 'DETAILS' && el.classList.contains('faq-item')) item = el;
    else if (el.closest) item = el.closest('details.faq-item');
    if (!item) return;
    var inAnswer = el.classList && (el.classList.contains('faq-a') || el.classList.contains('faq-a-inner') || el.classList.contains('faq-a-content'));
    if (!inAnswer && el.closest) inAnswer = !!el.closest('.faq-a, .faq-a-inner, .faq-a-content');
    if (!inAnswer) return;
    window.setTimeout(function () {
        setFaqItemOpen(item, true);
    }, 0);
}

