    var doc = ev.currentTarget;
    var target = ev.target;
    if (!target || !target.closest) return;
    var summary = target.closest('summary.faq-q, .faq-q');
    if (!summary) return;
    var item = getFaqItemFromTarget(target);
    if (!item) return;

    if (ev.type === 'mousedown') {
        ev.preventDefault();
        ev.stopPropagation();
        toggleFaqItemInDoc(doc, item);
        return;
    }
    if (ev.type === 'click') {
        ev.preventDefault();
        ev.stopPropagation();
    }
}

