function protectDecorLayers() {
    if (!editor) return;
    var i, j, cls, items, item, styleKeys, k, key;
    styleKeys = ['position', 'top', 'left', 'right', 'bottom', 'width', 'height', 'max-width', 'min-height', 'margin', 'padding', 'display'];
    for (i = 0; i < decorLayerClasses.length; i++) {
        cls = decorLayerClasses[i];
        items = editor.getWrapper().find('.' + cls);
        if (!items || !items.length) continue;
        for (j = 0; j < items.length; j++) {
            item = items[j];
            item.set({
                removable: false,
                copyable: false,
                draggable: false,
                selectable: false,
                hoverable: false,
                badgable: false,
                layerable: true,
                highlightable: false
            });
            if (item.removeStyle) {
                for (k = 0; k < styleKeys.length; k++) {
                    key = styleKeys[k];
                    item.removeStyle(key);
                }
            }
        }
    }
}

