var fs = require('fs');
var path = require('path');

var root = path.join(__dirname, '..');
var ascxPath = path.join(root, 'HOS', 'Controls', 'Information', 'TiemChung', 'SectionTiemChung.ascx');
var fragmentPath = path.join(root, 'SQL', 'CHUYENDOI', 'TiemChung', '_html_seed_fragment.txt');
var sqlPath = path.join(root, 'SQL', 'CHUYENDOI', 'TiemChung', '02_CMS_TiemChungFullPage_Insert_NoiDungHienTai.sql');

var ascx = fs.readFileSync(ascxPath, 'utf8');
var startMarker = '<!-- 00 - Hero -->';
var endMarker = '</section>\r\n\r\n<% if (!HasFullPage && !RenderRegisterForm) { %>';

var start = ascx.indexOf(startMarker);
var end = ascx.indexOf(endMarker);
if (start < 0 || end < 0 || end <= start) {
    endMarker = '</section>\n\n<% if (!HasFullPage && !RenderRegisterForm) { %>';
    end = ascx.indexOf(endMarker);
}
if (start < 0 || end < 0 || end <= start) {
    throw new Error('Khong tim thay khoi HTML fallback trong SectionTiemChung.ascx');
}

var sections = ascx.substring(start, end).replace(/\r\n/g, '\n').trim();
var htmlBody = [
    '<div class="tiem-chung-page" data-tiem-chung-root="1">',
    '<div class="tiem-chung-page-body">',
    sections,
    '</div>',
    '</div>'
].join('\n');

fs.writeFileSync(fragmentPath, htmlBody + '\n', 'utf8');

function sqlEscape(value) {
    return value.replace(/'/g, "''");
}

function chunkSql(value, chunkSize) {
    var chunks = [];
    var i = 0;
    while (i < value.length) {
        chunks.push("SET @HtmlBodyVi = @HtmlBodyVi + N'" + sqlEscape(value.substring(i, i + chunkSize)) + "'");
        i += chunkSize;
    }
    return chunks.join('\n');
}

var sqlHeader = fs.readFileSync(sqlPath, 'utf8').split('DECLARE @HtmlBodyVi')[0];
var sqlFooter = [
    '',
