public static string NormalizeTiemChungShell(string html)
{
    if (string.IsNullOrEmpty(html)) return string.Empty;

    string value = html.Trim();
    value = Regex.Replace(
        value,
        @"(<div\s+class\s*=\s*(?:""tiem-chung-page""|'tiem-chung-page')[^>]*>\s*<div\s+class\s*=\s*(?:""tiem-chung-page-body""|'tiem-chung-page-body')[^>]*>)\s*<div\s+class\s*=\s*(?:""tiem-chung-page""|'tiem-chung-page')[^>]*>\s*<div\s+class\s*=\s*(?:""tiem-chung-page-body""|'tiem-chung-page-body')[^>]*>",
        "$1",
        RegexOptions.IgnoreCase);
    value = Regex.Replace(
        value,
        @"(</div>\s*</div>)\s*(</div>\s*</div>)\s*$",
        "$2",
        RegexOptions.IgnoreCase);
    return value;
}

private static Dictionary<string, object> SanitizePageRow(DataRow row)
{
    Dictionary<string, object> result = RowToDictionary(row);
    SanitizePagePayload(result);
    return result;
}

private static void SanitizePagePayload(Dictionary<string, object> payload)
{
    if (payload == null) return;

    SanitizePayloadHtmlField(payload, "HtmlBodyVi");
    SanitizePayloadHtmlField(payload, "HtmlBodyEn");
}

private static void SanitizePayloadHtmlField(Dictionary<string, object> payload, string key)
{
    object raw;
    if (!payload.TryGetValue(key, out raw) || raw == null) return;

    string html = SanitizeHtml(Convert.ToString(raw));
    payload[key] = html;
}

