USE [thienhaso_WEB_His_TimTamDuc_2025]
GO

/*
    Sua HTML Tiem Chung bi lo mã ASP.NET tu file seed cu:
    <% if (HasFullPage) { %> ... <% } else { %>

    Chay sau khi deploy handler moi (co SanitizeHtml + NormalizeTiemChungShell).
    Script nay goi lai CMS_TiemChungPage_SaveCMS voi HTML da loc.
*/

SET NOCOUNT ON
SET XACT_ABORT ON

IF OBJECT_ID(N'dbo.CMS_TiemChungPageVersion', N'U') IS NULL
BEGIN
    RAISERROR(N'Chua co bang CMS_TiemChungPageVersion.', 16, 1)
    RETURN
END

DECLARE @VersionId INT
DECLARE @Title NVARCHAR(500)
DECLARE @Slug NVARCHAR(200)
DECLARE @MetaDescription NVARCHAR(1000)
DECLARE @HtmlBodyVi NVARCHAR(MAX)
DECLARE @HtmlBodyEn NVARCHAR(MAX)
DECLARE @CssText NVARCHAR(MAX)
DECLARE @ProjectJsonVi NVARCHAR(MAX)
DECLARE @ProjectJsonEn NVARCHAR(MAX)

Select Top 1
    @VersionId = TiemChungPageVersionID,
    @Title = Title,
    @Slug = Slug,
    @MetaDescription = MetaDescription,
    @HtmlBodyVi = HtmlBodyVi,
    @HtmlBodyEn = HtmlBodyEn,
    @CssText = CssText,
    @ProjectJsonVi = ProjectJsonVi,
    @ProjectJsonEn = ProjectJsonEn
From CMS_TiemChungPageVersion
Where IsPublished = 1
Order By VersionNo Desc

IF @VersionId IS NULL
BEGIN
    RAISERROR(N'Khong tim thay version dang xuat ban.', 16, 1)
    RETURN
END

IF @HtmlBodyVi LIKE '%<%' OR @HtmlBodyVi LIKE '%HasFullPage%' OR @HtmlBodyVi LIKE '%FullPageHtml%'
   OR @HtmlBodyEn LIKE '%<%' OR @HtmlBodyEn LIKE '%HasFullPage%' OR @HtmlBodyEn LIKE '%FullPageHtml%'
BEGIN
    SET @HtmlBodyVi = dbo.CMS_TiemChungPage_SanitizeHtml(@HtmlBodyVi)
    SET @HtmlBodyEn = dbo.CMS_TiemChungPage_SanitizeHtml(@HtmlBodyEn)

    EXEC dbo.CMS_TiemChungPage_SaveCMS
        @Title = @Title,
        @Slug = @Slug,
        @MetaDescription = @MetaDescription,
        @HtmlBodyVi = @HtmlBodyVi,
        @HtmlBodyEn = @HtmlBodyEn,
        @CssText = @CssText,
        @ProjectJsonVi = @ProjectJsonVi,
        @ProjectJsonEn = @ProjectJsonEn,
        @Publish = 1,
        @UserName = N'fix-asp-leak'

    PRINT N'Da luu lai HTML sau khi loc mã ASP.NET.'
END
ELSE
BEGIN
    PRINT N'HTML hien tai khong co dau hieu lo mã ASP.NET — khong can sua.'
END
GO

