function registerThemeTraits(ed) {
    var domc = ed.DomComponents;

    function removeThemeClasses(component, classList) {
        var i;
        for (i = 0; i < classList.length; i++) {
            if (component.getClasses().indexOf(classList[i]) >= 0) {
                component.removeClass(classList[i]);
            }
        }
    }

    function addClassThemeType(typeName, matchClass, traitLabel, traitName, options, fallback) {
        var values = [];
        var i;
        for (i = 0; i < options.length; i++) values.push(options[i].value);

        domc.addType(typeName, {
            extend: 'default',
            isComponent: function (el) {
                if (el && el.classList && el.classList.contains(matchClass)) {
                    return { type: typeName };
                }
            },
            model: {
                defaults: {
                    traits: [{
                        type: 'select',
                        label: traitLabel,
                        name: traitName,
                        changeProp: true,
                        options: options
                    }]
                },
                init: function () {
                    var self = this;
                    var classes = self.getClasses();
                    var initial = fallback;
                    var j;
                    for (j = 0; j < options.length; j++) {
                        if (classes.indexOf(options[j].value) >= 0) {
                            initial = options[j].value;
                            break;
                        }
                    }
                    if (!self.get(traitName)) self.set(traitName, initial);
                    self.on('change:' + traitName, function () {
                        var value = self.get(traitName) || fallback;
