            if (component.getClasses().indexOf(classList[i]) >= 0) {
                component.removeClass(classList[i]);
            }
        }
    }

    function readStyleBgColor(component) {
        var style = component.getStyle() || {};
        return style['background-color'] || style.backgroundColor || style.background || '';
    }

    function addClassThemeType(typeName, matchClass, traitLabel, traitName, options, fallback) {
        var values = [];
