                        removeThemeClasses(self, values);
                        self.addClass(value);
                        markDirty();
                    });
                }
            }
        });
    }

    function addCardBgType(typeName, matchClass, semanticClasses) {
        var semantic = semanticClasses || [];
        var allRemove = allTcBgClasses.concat(semantic);

        domc.addType(typeName, {
            extend: 'default',
            isComponent: function (el) {
                if (el && el.classList && el.classList.contains(matchClass)) {
                    return { type: typeName };
                }
            },
            model: {
                defaults: {
                    traits: [
                        {
                            type: 'select',
                            label: 'Bo mau nen',
                            name: 'tcCardBgPreset',
                            changeProp: true,
                            options: cardBgPresets
                        },
                        {
                            type: 'color',
                            label: 'Mau nen tuy chinh',
                            name: 'tcCardBgColor',
                            changeProp: true
                        }
                    ]
                },
                init: function () {
                    var self = this;
                    var classes = self.getClasses();
                    var key;
                    var preset = '';
                    var j;
                    var custom = readStyleBgColor(self);

                    for (j = 0; j < allTcBgClasses.length; j++) {
                        if (classes.indexOf(allTcBgClasses[j]) >= 0) {
                            preset = allTcBgClasses[j];
                            break;
                        }
                    }
                    if (!preset) {
                        for (key in semanticBgMap) {
                            if (semanticBgMap.hasOwnProperty(key) && classes.indexOf(key) >= 0) {
                                preset = semanticBgMap[key];
                                break;
                            }
                        }
                    }

                    if (!self.get('tcCardBgPreset') && preset) self.set('tcCardBgPreset', preset);
                    if (!self.get('tcCardBgColor') && custom) self.set('tcCardBgColor', custom);

