        "$1",
        RegexOptions.IgnoreCase);
    value = Regex.Replace(
        value,
        @"(</div>\s*</div>)\s*(</div>\s*</div>)\s*$",
        "$2",
        RegexOptions.IgnoreCase);
    return value;
}

